private static final String HAPBEAT_SESSION_TICKET_EXTRA = "com.hapbeat.demo_session.ticket";

/** Returns the session ticket extra of the launching Intent once (it is removed), or null. */
public String AndroidThunkJava_HapbeatSession_TakeTicket()
{
    Intent intent = getIntent();
    if (intent == null || !intent.hasExtra(HAPBEAT_SESSION_TICKET_EXTRA))
    {
        return null;
    }
    String ticket = null;
    try
    {
        ticket = intent.getStringExtra(HAPBEAT_SESSION_TICKET_EXTRA);
    }
    catch (Exception e)
    {
        Log.debug("HapbeatDemoSession: ticket extra unreadable: " + e);
    }
    intent.removeExtra(HAPBEAT_SESSION_TICKET_EXTRA);
    setIntent(intent);
    return ticket;
}

/** assets/hapbeat-demo-session.json as UTF-8 (at most 16384 bytes), or null. */
public String AndroidThunkJava_HapbeatSession_ReadDescriptor()
{
    try (java.io.InputStream input = getAssets().open("hapbeat-demo-session.json"))
    {
        java.io.ByteArrayOutputStream output = new java.io.ByteArrayOutputStream();
        byte[] buffer = new byte[4096];
        int count;
        while ((count = input.read(buffer)) > 0)
        {
            output.write(buffer, 0, count);
            if (output.size() > 16384)
            {
                return null;
            }
        }
        return new String(output.toByteArray(), java.nio.charset.StandardCharsets.UTF_8);
    }
    catch (Exception e)
    {
        Log.debug("HapbeatDemoSession: descriptor unreadable: " + e);
        return null;
    }
}

/** getExternalFilesDir(null)/hapbeat-device.json (the per-device Hapbeat address), or null without that directory. */
public String AndroidThunkJava_HapbeatSession_DeviceAddressPath()
{
    java.io.File dir = getExternalFilesDir(null);
    return dir == null ? null : new java.io.File(dir, "hapbeat-device.json").getAbsolutePath();
}

/** hapbeat-device.json as UTF-8, or null when it is absent, unreadable or larger than 1024 bytes. */
public String AndroidThunkJava_HapbeatSession_ReadDeviceAddress()
{
    String path = AndroidThunkJava_HapbeatSession_DeviceAddressPath();
    if (path == null)
    {
        return null;
    }
    java.io.File file = new java.io.File(path);
    if (!file.isFile())
    {
        return null;
    }
    try (java.io.InputStream input = new java.io.FileInputStream(file))
    {
        java.io.ByteArrayOutputStream output = new java.io.ByteArrayOutputStream();
        byte[] buffer = new byte[1025];
        int count;
        while ((count = input.read(buffer)) > 0)
        {
            output.write(buffer, 0, count);
            if (output.size() > 1024)
            {
                Log.warn("HAPBEAT_DEVICE_ADDRESS_REJECTED larger than 1024 bytes source=" + path);
                return null;
            }
        }
        return new String(output.toByteArray(), java.nio.charset.StandardCharsets.UTF_8);
    }
    catch (Exception e)
    {
        Log.warn("HAPBEAT_DEVICE_ADDRESS_REJECTED unreadable source=" + path + ": " + e);
        return null;
    }
}

/**
 * Starts the next runtime with an explicit Intent and NEW_TASK | CLEAR_TASK; an empty ticket starts it without
 * the extra (Hub に戻る). True when the request was accepted.
 */
public boolean AndroidThunkJava_HapbeatSession_Launch(String packageName, String activityName, String ticket)
{
    try
    {
        Intent intent = new Intent();
        intent.setClassName(packageName, activityName);
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
        if (ticket != null && !ticket.isEmpty())
        {
            intent.putExtra(HAPBEAT_SESSION_TICKET_EXTRA, ticket);
        }
        startActivity(intent);
        return true;
    }
    catch (Exception e)
    {
        Log.debug("HapbeatDemoSession: launch failed: " + e);
        return false;
    }
}

/** Whether the package is installed (it must be listed in the manifest's queries). */
public boolean AndroidThunkJava_HapbeatSession_IsInstalled(String packageName)
{
    try
    {
        getPackageManager().getPackageInfo(packageName, 0);
        return true;
    }
    catch (Exception e)
    {
        return false;
    }
}

private android.net.wifi.WifiManager.MulticastLock HapbeatSessionMulticastLock;

/** Acquires (held) or releases the Demo Switch receiver's Wi-Fi MulticastLock. True when the lock is now held. */
public boolean AndroidThunkJava_HapbeatSession_SetMulticastLock(boolean held)
{
    try
    {
        if (!held)
        {
            if (HapbeatSessionMulticastLock != null && HapbeatSessionMulticastLock.isHeld())
            {
                HapbeatSessionMulticastLock.release();
            }
            return false;
        }
        if (HapbeatSessionMulticastLock == null)
        {
            android.net.wifi.WifiManager wifi = (android.net.wifi.WifiManager)getApplicationContext().getSystemService(android.content.Context.WIFI_SERVICE);
            if (wifi == null)
            {
                return false;
            }
            HapbeatSessionMulticastLock = wifi.createMulticastLock("HapbeatDemoSwitch");
            HapbeatSessionMulticastLock.setReferenceCounted(false);
        }
        if (!HapbeatSessionMulticastLock.isHeld())
        {
            HapbeatSessionMulticastLock.acquire();
        }
        return true;
    }
    catch (Exception e)
    {
        Log.debug("HapbeatDemoSession: multicast lock unavailable: " + e);
        return false;
    }
}

public void AndroidThunkJava_HapbeatSession_FinishTask()
{
    runOnUiThread(new Runnable()
    {
        @Override
        public void run()
        {
            finishAndRemoveTask();
        }
    });
}
